// App.js
import React, { useState, useEffect } from 'react';
import { SafeAreaView, View, Text, TouchableOpacity, StatusBar, Appearance } from 'react-native';
import { SafeAreaProvider } from 'react-native-safe-area-context';

// Remarque: NativeWind utilise `className`
// Assure-toi que NativeWind est configuré dans ton projet.

export default function App() {
  // initial : suit la préférence système
  const colorScheme = Appearance.getColorScheme();
  const [isDark, setIsDark] = useState(colorScheme === 'dark');

  useEffect(() => {
    const sub = Appearance.addChangeListener(({ colorScheme }) => {
      // si tu veux suivre automatiquement le système, décommente :
      // setIsDark(colorScheme === 'dark');
    });
    return () => sub.remove();
  }, []);

  return (
    // on applique 'dark' comme classe au parent si isDark === true
    <SafeAreaProvider>
      <View className={isDark ? 'dark' : ''}>
        {/* StatusBar pour que la barre prenne la bonne couleur */}
        <StatusBar barStyle={isDark ? 'light-content' : 'dark-content'} />

        <SafeAreaView className="min-h-screen bg-white dark:bg-bg-dark">
          <View className="px-4 py-6">
            <Text className="text-2xl font-bold text-text-light dark:text-text-dark">
              Exemple : Mode {isDark ? 'Sombre' : 'Clair'}
            </Text>

            <Text className="mt-2 text-sm text-muted-light dark:text-muted-dark">
              Ceci est un exemple de texte qui change selon le thème.
            </Text>

            <View className="mt-6 flex-row items-center justify-between">
              <TouchableOpacity
                onPress={() => setIsDark(!isDark)}
                className="px-4 py-2 rounded-lg bg-primary-500/90"
              >
                <Text className="text-white font-semibold">
                  Basculer le thème
                </Text>
              </TouchableOpacity>

              <View className="px-4 py-2 rounded-lg bg-surface-light dark:bg-surface-dark">
                <Text className="text-sm text-text-light dark:text-text-dark">Carte / Surface</Text>
              </View>
            </View>
          </View>
        </SafeAreaView>
      </View>
    </SafeAreaProvider>
  );
}
